"""Minimal stand-in for pytest: just enough to execute this suite offline."""
import contextlib

class _Raises:
    def __init__(self, exc): self.exc = exc
    def __enter__(self): return self
    def __exit__(self, et, ev, tb):
        if et is None:
            raise AssertionError(f"DID NOT RAISE {self.exc.__name__}")
        return issubclass(et, self.exc)

def raises(exc): return _Raises(exc)

class _Mark:
    def __getattr__(self, name):
        def deco(*a, **k):
            if a and callable(a[0]): return a[0]
            return lambda f: f
        return deco
mark = _Mark()
EOF
cat > /tmp/shim/run.py <<'EOF'
import importlib, sys, traceback
mod = importlib.import_module(sys.argv[1])
tests = [(n, f) for n, f in vars(mod).items() if n.startswith("test_") and callable(f)]
fails = 0
for name, fn in tests:
    try:
        fn()
        print(f"PASS {name}")
    except Exception:
        fails += 1
        print(f"FAIL {name}")
        traceback.print_exc()
print(f"\n{len(tests)-fails} passed, {fails} failed")
sys.exit(1 if fails else 0)
EOF
cd /app && PYTHONPATH=/tmp/shim:/app python3 /tmp/shim/run.py test_setup_language_detection; echo "exit=$?"

